package com.amit.jobagent.application;import com.amit.jobagent.common.api.PagedResponse;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1")public class ApplicationHandoffController{private final ApplicationHandoffService service;public ApplicationHandoffController(ApplicationHandoffService s){service=s;}@PostMapping("/application-packages/{packageId}/revisions/{revisionId}/handoffs")ApplicationHandoffResponse create(@PathVariable UUID packageId,@PathVariable UUID revisionId,@RequestHeader("Idempotency-Key")String key){return service.create(packageId,revisionId,key);}@GetMapping("/application-handoffs")PagedResponse<ApplicationHandoffResponse>list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.list(page,size);}@GetMapping("/application-handoffs/{id}")ApplicationHandoffResponse get(@PathVariable UUID id){return service.get(id);}@GetMapping("/application-handoffs/{id}/eligibility")HandoffEligibilityResponse eligibility(@PathVariable UUID id){return service.eligibility(id);}@GetMapping("/application-handoffs/{id}/submission-kit")SubmissionKitResponse kit(@PathVariable UUID id){return service.kit(id);}@PostMapping("/application-handoffs/{id}/launch")LaunchResponse launch(@PathVariable UUID id,@Valid@RequestBody HandoffStateRequest request,@RequestHeader("Idempotency-Key")String key){return service.launch(id,request,key);}@PostMapping("/application-handoffs/{id}/report-submitted")ApplicationHandoffResponse submitted(@PathVariable UUID id,@Valid@RequestBody HandoffStateRequest request,@RequestHeader("Idempotency-Key")String key){return service.submitted(id,request,key);}@PostMapping("/application-handoffs/{id}/mark-not-submitted")ApplicationHandoffResponse notSubmitted(@PathVariable UUID id,@Valid@RequestBody HandoffStateRequest request,@RequestHeader("Idempotency-Key")String key){return service.notSubmitted(id,request,key);}@PostMapping("/application-handoffs/{id}/cancel")ApplicationHandoffResponse cancel(@PathVariable UUID id,@Valid@RequestBody HandoffStateRequest request,@RequestHeader("Idempotency-Key")String key){return service.cancel(id,request,key);}}
